void jbd2_journal_unlock_updates (journal_t *journal) /* <=== jbd2_journal_unlock_updates */ 
{
	J_ASSERT(journal->j_barrier_count != 0);

	mutex_unlock(&journal->j_barrier);
	write_lock(&journal->j_state_lock);
