static inline u32 new_encode_dev(dev_t dev) /* <=== new_encode_dev */ 
{
	unsigned major = MAJOR(dev);
	unsigned minor = MINOR(dev);
	return (minor & 0xff) | (major << 8) | ((minor & ~0xff) << 12);
