void call_rcu(struct rcu_head *head, void (*func)(struct rcu_head *head)) /* <=== call_rcu */ 
{
	head->func = func;
	head->next = rcuhead;
	rcuhead = head;
	if (!rcutail)
		rcutail = head;
	nr_rcuhead++;
	if (nr_rcuhead >= 1000) {
		int signal = 0;

		pthread_mutex_lock(&rculock);
		if (!rcuhead_global)
			signal = 1;
		rcutail->next = rcuhead_global;
		rcuhead_global = head;
		pthread_mutex_unlock(&rculock);

		nr_rcuhead = 0;
		rcuhead = NULL;
		rcutail = NULL;

		if (signal) {
			pthread_cond_signal(&rcu_worker_cond);
		}
	}
}

