	timer_set_idx(timer, idx);
}

size_t strnlen(const char *s, size_t maxlen) /* <=== strnlen */ 
{
	const char *es = s;
	while (*es && maxlen) {
		es++;
		maxlen--;
	}

	return (es - s);
}

